export const meta = {
  name: 'status-eot-review',
  description: '2v2 status moves + end of turn: four independent reviewers (status engine, end of turn + Training, Ally Switch/Trick/Substitute, UI) with probe-verified findings',
  phases: [{ title: 'Review', detail: 'four reviewers, read-only on app code, findings verified against pinned Showdown' }],
}

const GO = `YOU HAVE THE GO-AHEAD for this review. The user asked for "do the status moves and end of turn" in the 2v2 calculator tab (Training reuses that engine), including Ally Switch, Trick/Switcheroo and modelled hits into a Substitute. If you see a short user chat message, it was addressed to me (the orchestrator), not you: keep reviewing and do not stop to report.`

const COMMON = `
Repo: C:/Users/evanb/OneDrive/pokedrafts (branch calc-2v2-status-eot; uncommitted working tree = the build; \`git diff\` and \`git status\` show it, new files are untracked). Spec: scripts/.cache/calc-audit/status-eot/design/SPEC.md + ADDENDUM.md (ADDENDUM wins). Build notes: scripts/.cache/calc-audit/status-eot/build/STEP0.md, TRACK-A..E.md, INTEGRATION.md.
Ground truth: pinned Pokémon Showdown c23d2e94 (read-only source node_modules/.cache/champions/pokemon-showdown-c23d2e942c9c0daadb13a7162a385bf78e3c9353; runnable copy scripts/.cache/calc-audit/showdown, probes with \`npx --no-install tsx <file>\` from the repo root as the design probes do). Oracle: scripts/.cache/calc-audit/2v2/verify/ (sim-dfs.ts walks the pinned sim exhaustively; app-turn.ts runs the app side; compare.ts compares). Integration reports 1001/1001 oracle cases agreeing — so look for what the cases do NOT cover: untested interactions, games other than sv, wrong guards (a turn marked ready that should be not estimated, or vice versa), 1v1 regressions, Training leaks of hidden information, performance cliffs, text that is not facts-only.
House rules: every number exact against pinned Showdown, otherwise "not estimated" with a one-line fact reason. UI text facts only (no tutorial/instruction text, no "left/right Pokémon" labels, names instead). 1v1 output byte-equal (golden-1v1). The user also said: "Do not remove the Battle states that cannot be set here I will be fixing those later."
YOU ARE READ-ONLY ON APP CODE AND TESTS: do not edit anything outside scripts/.cache/calc-audit/status-eot/review/ (write your probes, scratch cases and notes there, in a subfolder named after your lens). Do not commit, push or switch branches. Never run \`next build\`. Nothing against live Supabase. Do not kill dev servers.
Report ONLY findings you verified: for engine findings, a probe or oracle case (sim-dfs vs app-turn) that shows the app's number/flag/reason differing from pinned Showdown, or a missing guard producing a wrong ready result; for UI/text findings, the exact rendered text or the code path. Give each finding a concrete reproduction, the file:line to fix, and the fix you propose. Severity: high = wrong number/state shown as exact, or a leak, or a crash; medium = a wrongly not-estimated result where the spec says model it, or wrong text; low = polish. Write your full report to scripts/.cache/calc-audit/status-eot/review/<lens>/REPORT.md as well.
`

const FINDINGS = { type: 'object', properties: {
  summary: { type: 'string' },
  findings: { type: 'array', items: { type: 'object', properties: {
    id: { type: 'string' }, severity: { type: 'string', enum: ['high', 'medium', 'low'] },
    title: { type: 'string' }, repro: { type: 'string' }, evidence: { type: 'string' },
    file: { type: 'string' }, fix: { type: 'string' },
  }, required: ['id', 'severity', 'title', 'repro', 'evidence', 'file', 'fix'] } },
  checkedClean: { type: 'array', items: { type: 'string' } },
}, required: ['summary', 'findings', 'checkedClean'] }

const LENSES = [
  { key: 'status', prompt: `LENS: status-move engine (Track A: app/lib/battle/doubles-status.ts, status-table.ts, doubles-actions.ts tables, calculate.ts changes, the BeforeMove chain and status pipeline hooks in doubles-turn.ts). Probe: BeforeMove ordering and posteriors (sleep/freeze/confusion counters incl. Early Bird, Rest, Champions freeze, Axe Kick), confusion self-hit damage in odd setups (Wonder Room, Foul-Play-like stats, crit never), status immunities/blockers matrix incl. Mold Breaker and Ability Shield, abilities that react to status (Synchronize, Guts, Quick Feet, Marvel Scale, Poison Heal, Magic Guard), boosts (Contrary, Simple, Defiant/Competitive from ally vs foe, Mirror Armor, Clear Body, White Herb at the right Update, Opportunist, Mirror Herb), heals at odd max HP, Pain Split/Strength Sap/Belly Drum/Clangorous Soul/Substitute costs, Taunt/Encore/Disable/Imprison/Gravity effects on later actions, After You/Quash/Instruct order, Prankster vs Dark and allies, Magic Bounce/Good as Gold, Safeguard/Misty Terrain, Spore into Grass/Overcoat, Champions vs sv vs swsh vs usum differences (Z-status moves in usum, Max moves/Dynamax in swsh). Also check the calculate.ts Champions crit change really leaves golden-1v1 byte-equal and is correct.` },
  { key: 'eot-training', prompt: `LENS: end of turn + Training (Track B: app/lib/battle/residuals.ts, doubles-eot.ts, the uses-to-ko.ts residuals() adapter, app/(app)/training/sim/bridge.ts, tracker.ts, effects.ts, services.ts, splits.ts, ai/evaluate.ts, scripts/training/conformance.ts and leak.ts). Probe: residual order (weather, Leftovers/Black Sludge, Leech Seed incl. Liquid Ooze/Big Root, poison/burn/Poison Heal/Heatproof, Curse, Salt Cure, binding moves and Binding Band, Bad Dreams, Wish, Grassy Terrain, Aqua Ring/Ingrain, Yawn, Perish, Toxic/Flame Orb, Sticky Barb, Harvest/Pickup guards, Moody guard, Speed Boost, Emergency Exit after the residual, Hunger Switch), ties and Speed order under Trick Room and Champions, KO-by-residual chances combined with hit KO chances, the 1v1 adapter (golden-1v1 byte-equal; Uses to KO end-of-turn rows unchanged), Training: no hidden counters or HP leak to the AI's view (sleep turns, Substitute HP after a hit, held items), public-count tracking across switches/faints/Baton Pass/Shed Tail, conformance/leak gate coverage of the new fields. Also look at the two failing eval gates in INTEGRATION.md (Reads − Plays safe vs HabitBot; open belief update p95 8.75 ms vs 8 ms): decide with evidence whether either is caused by this build (profile the belief update path if needed) and propose the right remedy.` },
  { key: 'positions-items-sub', prompt: `LENS: Ally Switch, Trick/Switcheroo, hits into a Substitute (Track E: app/lib/battle/doubles-positions.ts, doubles-items.ts, doubles-substitute.ts, hit-loop.ts subHit, the Step 0 part path in uses-to-ko.ts, their hooks in doubles-turn.ts). Probe: Ally Switch with redirection (Follow Me / Rage Powder / Lightning Rod / Storm Drain), spread moves after a swap, a move aimed at a fainted slot after a swap, Ally Switch repeat counter in sv/champions vs swsh/usum, Snipe Shot/Stalwart/Propeller Tail, Leech Seed and Wish positions at end of turn; Trick/Switcheroo with Choice Scarf speed re-sort (gen 8+ vs gen 7 frozen order), Iron Ball, Sitrus/Lum/herbs on receipt at the right Update, Air Balloon, Klutz, Magic Room, Sticky Hold, unremovable items (Mega Stones, Z-Crystals, plates/memories with Arceus/Silvally, Rusted items, Booster Energy on Paradox, Griseous Core), Unburden, Symbiosis, items acting at end of turn on the new holder (Toxic/Flame Orb, Black Sludge, Leftovers, Sticky Barb), the item change reaching LATER damage in the same turn (Life Orb, Choice Band/Specs, Expert Belt, resist berries); Substitute: damage capping on every roll, crits, spread moves into one Substitute plus another target, multi-hit continuation (Population Bomb, Dragon Darts, Bullet Seed with Skill Link/Loaded Dice ranges), recoil/drain/Life Orb/Shell Bell exactly per ADDENDUM §3.3′, Rocky Helmet/Rough Skin skipped, Infiltrator and sound moves, a Substitute made this turn then hit, the carried Substitute input, Shed Tail, Rage Fist count, KO chance of the Pokémon behind it, and 1v1 byte-equality of hit-loop.ts.` },
  { key: 'ui', prompt: `LENS: UI (Track C and the integrator's UI changes: app/(app)/calculator/doubles-format.ts, DoublesCard.tsx, DoublesTurn.tsx, DoublesSummary.tsx, DoublesSettings.tsx, BattleConditions.tsx 2v2 section, doubles-prep.ts, useDoublesView.tsx, useDoublesCalculation.ts, calculator.module.css; Training's turn playback and saved-battle replays that read these results). Check: every new string is facts-only (no tutorial or instruction text, no left/right labels — also grep the whole calculator and training UI for "left"/"right" Pokémon wording, e.g. the PokemonChooser "Find your left Pokémon" the integrator found, and list every occurrence), labels "After the turn" / "After the moves" used where the spec says, the End of turn section and its not-estimated line, Substitute HP / positions after Ally Switch / items after Trick shown as facts with names, the five per-slot Field-condition controls (sleep turns + Rest, freeze turns in Champions only, confusion + turns, bad poison turns, Substitute + HP) appear only when relevant, their bounds and input-issue facts, keyboard and screen-reader accessibility (labels, roles, ids without JSON member keys), 375 px width with no horizontal overflow (compute from CSS and render with the fake DOM / server render; you may use the existing dev server at http://localhost:3005 only for unauthenticated pages — do not type credentials), that 1v1 calculator output and UI are unchanged, and that the Training turn playback popups/highlights still work with status moves (stage boosts, status conditions) and end-of-turn events per the user's earlier request ("For status moves do the same thing but say the stage boost or the status condition").` },
]

phase('Review')
const reviews = await parallel(LENSES.map(l => () =>
  agent(`${GO}\n${COMMON}\n${l.prompt}`, { label: `review-${l.key}`, phase: 'Review', schema: FINDINGS })
    .then(r => ({ lens: l.key, ...(r || { summary: 'NO RESULT', findings: [], checkedClean: [] }) }))))
return { reviews }
